#!/usr/bin/env python3
"""Глава «Италия», пачка 4: от brigantaggio до Витторио-Венето, 12 уровней (акты XI–XII).

    python3 tools/batches/italy_4.py [repo_root]
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from italy_common import (char, scene, actor, setf, remf, addr, rule, flag, nflag, texts, level, run)

def C(id, name, emoji, tags=None):
    return char(id, name, tags or [id], emoji)

CH, SC, RU, LV, TX = [], [], [], [], {}

def L(id, mood, cover, panels, scenes, chars, flags, goal, solution, acc, title, gtext, hint, intro, fact, source):
    LV.append(level(id, mood, cover, panels, scenes, chars, flags, [], goal, solution, acc))
    TX.update(texts(id, title, gtext, hint, intro, fact, source))

def S(id, name, slots, emoji, action, icon, roles, donor):
    SC.append(scene(id, name, [f"sig_{id}"], slots, emoji, action, icon, roles, donor))

def Rl(id, comment, actors, effects, n=""):
    RU.append(rule(f"{id}{n}_sig", comment, f"sig_{id}", actors, effects))

